// Bundles the SQL migrations generated by drizzle-kit (drizzle/*.sql) into a TypeScript module,
// so the browser can apply them without a file system. Run after `drizzle-kit generate`.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

export function renderMigrations(root = ".") {
  const journal = JSON.parse(readFileSync(`${root}/drizzle/meta/_journal.json`, "utf8"));
  const entries = journal.entries.map((e) => ({
    tag: e.tag,
    statements: readFileSync(`${root}/drizzle/${e.tag}.sql`, "utf8")
      .replace(/\r\n/g, "\n")
      .split("--> statement-breakpoint")
      .map((s) => s.trim())
      .filter(Boolean),
  }));
  return (
    "// Generated by scripts/gen-migrations.mjs from drizzle/*.sql. Do not edit by hand.\n" +
    `export const MIGRATIONS: ReadonlyArray<{ tag: string; statements: readonly string[] }> = ${JSON.stringify(entries, null, 2)};\n`
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync("src/core/db/migrations.ts", renderMigrations());
  console.log("src/core/db/migrations.ts updated");
}
